    ["Off"] = "Vypnuto",
    ["OmniVoice is an optional add-on for computers with a capable GPU. Pocket TTS needs nothing extra."] = "OmniVoice je volitelný doplněk pro počítače s výkonnou grafickou kartou. Pocket TTS nepotřebuje nic navíc.",
    ["OmniVoice pack"] = "Balíček OmniVoice",
    ["OmniVoice · Balanced"] = "OmniVoice · Vyvážený",
    ["OmniVoice · High Quality"] = "OmniVoice · Vysoká kvalita",
