    ["OmniVoice · Ultra Quality"] = "OmniVoice · Ultra kvalita",
    ["On"] = "Zapnuto",
    ["One file with versions, settings and the latest log lines. It never contains your API key, tokens, voice recordings or conversation text."] = "Jeden soubor s verzemi, nastavením a posledními řádky logu. Nikdy neobsahuje tvůj klíč API, tokeny, hlasové nahrávky ani text konverzací.",
    ["Open"] = "Otevřít",
    ["Opening chat. Waiting for the conversation service."] = "Otevírá se chat. Čeká se na konverzační službu.",
    ["Ordinary"] = "Běžný",
    ["Page {page} / {pages}"] = "Strana {page} / {pages}",
