    ["RED4ext logs"] = "Logy RED4ext",
    ["RED4ext writes its logs in {path}"] = "RED4ext zapisuje své logy do: {path}",
    ["Raise or lower where companions look when they make eye contact with you."] = "Zvyš nebo sniž místo, kam se společníci dívají při očním kontaktu s tebou.",
    ["React to battles"] = "Reagovat na bitvy",
