    ["Return to conversation settings."] = "Návrat do nastavení konverzací.",
    ["Return to the memory controls."] = "Návrat k ovládání paměti.",
    ["Review the memory clear below, then choose Confirm or Cancel."] = "Zkontroluj vymazání paměti níže a potom zvol Potvrdit nebo Zrušit.",
    ["Romantic"] = "Romantický",
    ["Running"] = "Běží",
    ["SELECTED"] = "VYBRÁNO",
    ["SETTINGS"] = "NASTAVENÍ",
    ["Save a report file you can send to the developer. API keys, tokens, IDs, microphone audio and conversation text are left out. If the conversation service is not running, a shorter report is made from the files the game can read."] = "Ulož soubor s hlášením, který můžeš poslat vývojáři. Klíče API, tokeny, ID, zvuk z mikrofonu ani text konverzací v něm nejsou. Pokud konverzační služba neběží, vytvoří se kratší hlášení ze souborů, které hra umí přečíst.",
    ["Saved Chat cleanup could not be verified. Please wait for the memory service."] = "Úklid uloženého chatu se nepodařilo ověřit. Počkej prosím na službu paměti.",
    ["Saved at {path}"] = "Uloženo do: {path}",
    ["Saved reports"] = "Uložená hlášení",
    ["Scenery or a vehicle is blocking the companion position."] = "Pozici společníka blokuje kulisa nebo vozidlo.",
    ["Search a character by name. Each invitation reserves a place and starts preparation immediately."] = "Hledej postavu podle jména. Každá pozvánka si rezervuje místo a okamžitě spustí přípravu.",
    ["Search by character name or model record using Search settings. {query}"] = "Hledej podle jména postavy nebo záznamu modelu pomocí Hledání v nastavení. {query}",
    ["Search by character name using Search settings. {query}\nThe character can be outside your current party."] = "Hledej podle jména postavy pomocí Hledání v nastavení. {query}\nPostava může být mimo tvou aktuální skupinu.",
    ["Search names, models or settings..."] = "Hledat jména, modely nebo nastavení...",
    ["Select a destination on the map first."] = "Nejdřív vyber cíl na mapě.",
    ["Select {name} for memory controls. This does not invite them or change their conversation settings."] = "Vyber postavu pro ovládání paměti: {name}. Tím ji nepozveš ani nezměníš její nastavení konverzací.",
    ["Selected"] = "Vybráno",
    ["Selected character"] = "Vybraná postava",
    ["Send the generated report rather than raw log files. Open these locations only if the developer asks for a specific file."] = "Posílej vytvořené hlášení, ne surové soubory s logy. Tato umístění otevři, jen když vývojář požádá o konkrétní soubor.",
    ["Settings"] = "Nastavení",
    ["Settings are active, but could not be saved for next time."] = "Nastavení jsou aktivní, ale nepodařilo se je uložit pro příště.",
    ["Settings saved."] = "Nastavení uložena.",
    ["Shared across your saves"] = "Sdíleno napříč uloženými hrami",
    ["Short report saved because the conversation service could not build the full report: {path}"] = "Krátké hlášení uloženo, protože konverzační služba nemohla sestavit úplné: {path}",
    ["Short report saved because the conversation service did not answer: {path}"] = "Krátké hlášení uloženo, protože konverzační služba neodpověděla: {path}",
    ["Short report saved because the conversation service is not running: {path}"] = "Krátké hlášení uloženo, protože konverzační služba neběží: {path}",
    ["Show companion replies using the selected subtitle display."] = "Zobrazovat odpovědi společníků ve zvoleném způsobu titulků.",
    ["Show companion reply subtitles during conversations."] = "Zobrazovat titulky odpovědí společníků během konverzací.",
    ["Some game models have special rigs or roles and may not behave as ordinary companions."] = "Některé modely ze hry mají zvláštní rigy nebo role a nemusí se chovat jako běžní společníci.",
    ["Some model records could not be read."] = "Některé záznamy modelů se nepodařilo přečíst.",
    ["Stand near one of your owned cars, or summon one."] = "Stoupni si k jednomu ze svých aut nebo si jedno přivolej.",
    ["Stand near your owned car."] = "Stoupni si k svému autu.",
    ["Starting"] = "Spouštění",
    ["Starting trip"] = "Zahajuje se jízda",
    ["State: {state}"] = "Stav: {state}",
    ["Step out and wait for the previous driver cleanup to finish."] = "Vystup a počkej, až se dokončí úklid po předchozím řidiči.",
    ["Step out before starting a new companion trip."] = "Vystup, než zahájíš novou jízdu se společníkem.",
    ["Step out of the driver seat before asking your companion to drive."] = "Vystup z místa řidiče, než požádáš společníka o řízení.",
    ["Step out of the driver seat so your companion can get in."] = "Vystup z místa řidiče, aby mohl nastoupit tvůj společník.",
    ["Stop requested"] = "Zastavení vyžádáno",
    ["Stop the trip after returning to gameplay. Wait for the car to stop, then step out before dismissing the driver."] = "Zastaví jízdu po návratu do hry. Počkej, až auto zastaví, a vystup, než řidiče propustíš.",
    ["Stop the trip and step out before dismissing your driver."] = "Zastav jízdu a vystup, než řidiče propustíš.",
    ["Stop trip"] = "Zastavit jízdu",
    ["Stopped"] = "Zastaveno",
    ["Stopping"] = "Zastavování",
    ["Stopping the trip. Wait for the car to stop before stepping out."] = "Jízda se zastavuje. Než vystoupíš, počkej, až auto zastaví.",
    ["Strong"] = "Silné",
    ["Subtitle display"] = "Zobrazení titulků",
    ["Subtitles"] = "Titulky",
    ["Subtle"] = "Nenápadné",
    ["Support report saved: {path}"] = "Hlášení podpory uloženo: {path}",
    ["TALK TO {character}"] = "MLUVIT S: {character}",
    ["TEXT  >"] = "TEXT  >",
    ["Talk to companions in any language: each character answers in the language you use. It uses a multilingual copy of each character, so what they remember from these conversations is kept apart from your English ones; forgetting a character clears both. Pocket TTS speaks only English, so turning this on switches Companion voices to OmniVoice · Balanced when the optional OmniVoice pack is installed, or to Convai · Cloud voice otherwise; without the pack, Natural speech and Expressive emotions are turned off, because the cloud voice would read their tags aloud. Off by default."] = "Mluv se společníky v jakémkoli jazyce: každá postava odpovídá v jazyce, který použiješ. Využívá vícejazyčnou kopii každé postavy, takže to, co si z těchto konverzací pamatuje, je uloženo odděleně od tvých anglických konverzací; zapomenutím postavy se vymažou obě. Pocket TTS mluví jen anglicky, takže zapnutí této volby přepne Hlasy společníků na OmniVoice · Vyvážený, pokud je nainstalován volitelný balíček OmniVoice, jinak na Convai · Cloudový hlas; bez balíčku se Přirozená řeč a Výrazné emoce vypnou, protože by cloudový hlas četl jejich značky nahlas. Ve výchozím stavu vypnuto.",
    ["Pocket TTS speaks only English. Turn off Multilingual conversations to choose it."] = "Pocket TTS mluví jen anglicky. Chceš-li ho vybrat, vypni Vícejazyčné konverzace.",
    ["Multilingual conversations needs a voice that speaks every language, so {setting} was switched to {voice}."] = "Vícejazyčné konverzace vyžadují hlas, který mluví všemi jazyky, proto byla volba {setting} přepnuta na {voice}.",
    ["Natural speech and Expressive emotions need the OmniVoice pack while Multilingual conversations is on: the Convai cloud voice would read their tags aloud."] = "Přirozená řeč a Výrazné emoce vyžadují balíček OmniVoice, dokud jsou zapnuty Vícejazyčné konverzace: cloudový hlas Convai by četl jejich značky nahlas.",
